import { Router } from "express";
import {
  login,
  logout,
  profile,
  refresh,
  register,
} from "../controllers/auth.controller.js";
import { authenticate } from "../middlewares/auth.middleware.js";

const router = Router();

router.post("/register", register);
router.post("/login", login);
router.post("/refresh", refresh);
router.post("/logout", logout);
router.get("/me", authenticate, profile);

export default router;

/**
 * Role-Based Access Control (RBAC) Middleware
 * 
 * Permission Matrix:
 * - OWNER: Full access to all resources and team management
 * - ADMIN: Can manage all data except team settings
 * - MEMBER: Can view and create data, limited edit/delete
 * - VIEWER: Read-only access
 */

const PERMISSIONS = {
    // Sales permissions
    'sales:read': ['OWNER', 'ADMIN', 'MEMBER', 'VIEWER'],
    'sales:create': ['OWNER', 'ADMIN', 'MEMBER'],
    'sales:update': ['OWNER', 'ADMIN', 'MEMBER'],
    'sales:delete': ['OWNER', 'ADMIN'],

    // Campaign permissions
    'campaigns:read': ['OWNER', 'ADMIN', 'MEMBER', 'VIEWER'],
    'campaigns:create': ['OWNER', 'ADMIN', 'MEMBER'],
    'campaigns:update': ['OWNER', 'ADMIN', 'MEMBER'],
    'campaigns:delete': ['OWNER', 'ADMIN'],

    // Insight permissions
    'insights:read': ['OWNER', 'ADMIN', 'MEMBER', 'VIEWER'],
    'insights:create': ['OWNER', 'ADMIN', 'MEMBER'],
    'insights:update': ['OWNER', 'ADMIN', 'MEMBER'],
    'insights:delete': ['OWNER', 'ADMIN'],

    // Customer permissions
    'customers:read': ['OWNER', 'ADMIN', 'MEMBER', 'VIEWER'],
    'customers:create': ['OWNER', 'ADMIN', 'MEMBER'],
    'customers:update': ['OWNER', 'ADMIN', 'MEMBER'],
    'customers:delete': ['OWNER', 'ADMIN'],

    // Analytics permissions
    'analytics:read': ['OWNER', 'ADMIN', 'MEMBER', 'VIEWER'],

    // AI permissions
    'ai:query': ['OWNER', 'ADMIN', 'MEMBER'],

    // Import permissions
    'import:csv': ['OWNER', 'ADMIN'],

    // Team management permissions
    'team:read': ['OWNER', 'ADMIN'],
    'team:invite': ['OWNER', 'ADMIN'],
    'team:update': ['OWNER'],
    'team:delete': ['OWNER'],

    // File upload permissions
    'upload:file': ['OWNER', 'ADMIN', 'MEMBER']
};

/**
 * Check if user has required permission
 * @param {string} permission - Permission to check (e.g., 'sales:create')
 * @returns {Function} Express middleware
 */
export const requirePermission = (permission) => {
    return (req, res, next) => {
        const userRole = req.user?.role;

        if (!userRole) {
            return res.status(401).json({
                success: false,
                message: 'Authentication required'
            });
        }

        const allowedRoles = PERMISSIONS[permission];

        if (!allowedRoles) {
            console.error(`Unknown permission: ${permission}`);
            return res.status(500).json({
                success: false,
                message: 'Internal server error'
            });
        }

        if (!allowedRoles.includes(userRole)) {
            return res.status(403).json({
                success: false,
                message: `Insufficient permissions. Required: ${permission}`
            });
        }

        next();
    };
};

/**
 * Check if user has one of the required roles
 * @param {string[]} roles - Array of allowed roles
 * @returns {Function} Express middleware
 */
export const requireRole = (roles) => {
    return (req, res, next) => {
        const userRole = req.user?.role;

        if (!userRole) {
            return res.status(401).json({
                success: false,
                message: 'Authentication required'
            });
        }

        if (!roles.includes(userRole)) {
            return res.status(403).json({
                success: false,
                message: `Access denied. Required role: ${roles.join(' or ')}`
            });
        }

        next();
    };
};

/**
 * Check if user owns the resource or has admin privileges
 * Expects resourceUserId to be set in req by previous middleware
 */
export const requireOwnershipOrAdmin = (req, res, next) => {
    const userRole = req.user?.role;
    const userId = req.user?.id;
    const resourceUserId = req.resourceUserId;

    if (!userRole || !userId) {
        return res.status(401).json({
            success: false,
            message: 'Authentication required'
        });
    }

    // OWNER and ADMIN can access any resource in their company
    if (['OWNER', 'ADMIN'].includes(userRole)) {
        return next();
    }

    // Others can only access their own resources
    if (resourceUserId && resourceUserId === userId) {
        return next();
    }

    return res.status(403).json({
        success: false,
        message: 'You can only access your own resources'
    });
};

export default {
    requirePermission,
    requireRole,
    requireOwnershipOrAdmin,
    PERMISSIONS
};

import { verifyAccessToken } from "../utils/tokens.js";

export const authenticate = (req, res, next) => {
  const header = req.headers.authorization;
  if (!header || !header.startsWith("Bearer ")) {
    return res.status(401).json({ message: "Authentication required" });
  }

  const token = header.split(" ")[1];

  try {
    const payload = verifyAccessToken(token);
    req.user = {
      id: payload.sub,
      email: payload.email,
      role: payload.role,
      companyId: payload.companyId
    };
    return next();
  } catch (error) {
    return res.status(401).json({ message: "Invalid or expired token" });
  }
};

import { asyncHandler } from "../utils/asyncHandler.js";
import {
  getAccessExpiryMs,
  getRefreshExpiryMs,
  signAccessToken,
  signRefreshToken,
  verifyRefreshToken,
} from "../utils/tokens.js";
import { hashPassword, verifyPassword } from "../utils/password.js";
import { prisma } from "../services/prisma.service.js";
import { redis } from "../services/redis.service.js";

const buildAccessPayload = (user) => ({
  sub: user.id,
  email: user.email,
  role: user.role,
  companyId: user.companyId
});

const refreshCookieOptions = {
  httpOnly: true,
  secure: process.env.NODE_ENV === "production",
  sameSite: "strict",
  path: "/",
  maxAge: getRefreshExpiryMs(),
};

const setRefreshCookie = (res, token) => {
  res.cookie("refreshToken", token, refreshCookieOptions);
};

const clearRefreshCookie = (res) => {
  res.clearCookie("refreshToken", { path: "/" });
};

const revokeRefreshToken = async (token) => {
  if (!token) {
    return;
  }

  await prisma.refreshToken.updateMany({
    where: { token },
    data: { revoked: true },
  });

  if (redis) {
    await redis.sadd("revoked_tokens", token);
  }
};

const createSession = async (user, res) => {
  const accessPayload = buildAccessPayload(user);
  const accessToken = signAccessToken(accessPayload);
  const refreshToken = signRefreshToken(accessPayload);

  await prisma.refreshToken.create({
    data: {
      userId: user.id,
      token: refreshToken,
      expiresAt: new Date(Date.now() + getRefreshExpiryMs()),
    },
  });

  setRefreshCookie(res, refreshToken);

  return { accessToken };
};

export const register = asyncHandler(async (req, res) => {
  const { name, email, password, companyName, industry } = req.body ?? {};

  if (!name || !email || !password) {
    return res.status(400).json({ message: "Name, email, and password required" });
  }

  const normalizedEmail = email.toLowerCase();
  const existing = await prisma.user.findUnique({
    where: { email: normalizedEmail },
  });

  if (existing) {
    return res.status(409).json({ message: "Email already registered" });
  }

  const passwordHash = await hashPassword(password);

  // Create company if provided
  let company = null;
  if (companyName) {
    company = await prisma.company.create({
      data: {
        name: companyName,
        industry: industry || null
      }
    });
  }

  const user = await prisma.user.create({
    data: {
      name,
      email: normalizedEmail,
      passwordHash,
      companyId: company?.id || null,
      role: company ? 'OWNER' : 'OWNER' // Default to OWNER
    },
  });

  const session = await createSession(user, res);
  return res.status(201).json({
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
      companyId: user.companyId
    },
    accessToken: session.accessToken,
    expiresIn: getAccessExpiryMs(),
  });
});

export const login = asyncHandler(async (req, res) => {
  const { email, password } = req.body ?? {};

  if (!email || !password) {
    return res.status(400).json({ message: "Email and password required" });
  }

  const normalizedEmail = email.toLowerCase();
  const user = await prisma.user.findUnique({
    where: { email: normalizedEmail },
  });

  if (!user) {
    return res.status(401).json({ message: "Invalid credentials" });
  }

  const isValid = await verifyPassword(password, user.passwordHash);
  if (!isValid) {
    return res.status(401).json({ message: "Invalid credentials" });
  }

  await prisma.refreshToken.updateMany({
    where: { userId: user.id, revoked: false },
    data: { revoked: true },
  });

  const session = await createSession(user, res);

  return res.json({
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
    },
    accessToken: session.accessToken,
    expiresIn: getAccessExpiryMs(),
  });
});

export const refresh = asyncHandler(async (req, res) => {
  const token = req.cookies?.refreshToken;
  if (!token) {
    return res.status(401).json({ message: "Refresh token missing" });
  }

  if (redis) {
    const isRevoked = await redis.sismember("revoked_tokens", token);
    if (isRevoked) {
      clearRefreshCookie(res);
      return res.status(401).json({ message: "Token revoked" });
    }
  }

  let payload;
  try {
    payload = verifyRefreshToken(token);
  } catch (error) {
    clearRefreshCookie(res);
    return res.status(401).json({ message: "Invalid refresh token" });
  }

  const storedToken = await prisma.refreshToken.findUnique({
    where: { token },
    include: { user: true },
  });

  if (!storedToken || storedToken.revoked || !storedToken.user) {
    clearRefreshCookie(res);
    return res.status(401).json({ message: "Refresh token not recognized" });
  }

  if (storedToken.expiresAt.getTime() < Date.now()) {
    clearRefreshCookie(res);
    await revokeRefreshToken(token);
    return res.status(401).json({ message: "Refresh token expired" });
  }

  await revokeRefreshToken(token);

  const session = await createSession(storedToken.user, res);
  return res.json({
    accessToken: session.accessToken,
    expiresIn: getAccessExpiryMs(),
  });
});

export const logout = asyncHandler(async (req, res) => {
  const token = req.cookies?.refreshToken;
  if (token) {
    await revokeRefreshToken(token);
  }
  clearRefreshCookie(res);
  return res.status(204).send();
});

export const profile = asyncHandler(async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.id },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      createdAt: true,
    },
  });

  if (!user) {
    return res.status(404).json({ message: "User not found" });
  }

  return res.json({ user });
});

import Redis from "ioredis";

const redisUrl = process.env.REDIS_URL;

export const redis = redisUrl
  ? new Redis(redisUrl, { lazyConnect: true })
  : null;

export const initRedis = async () => {
  if (!redis) {
    console.warn("Redis URL not provided. Queue features will be disabled.");
    return;
  }

  if (redis.status === "ready") {
    return;
  }

  try {
    await redis.connect();
  } catch (error) {
    console.error("Failed to connect to Redis", error);
    throw error;
  }
};

if (redis) {
  redis.on("error", (err) => {
    console.error("Redis error:", err);
  });
}

export const disconnectRedis = async () => {
  if (!redis) {
    return;
  }

  try {
    await redis.quit();
  } catch (error) {
    console.error("Failed to close Redis connection", error);
  }
};

import { redis } from "../services/redis.service.js";
import { asyncHandler } from "../utils/asyncHandler.js";

const MAX_REQUESTS = Number(process.env.RATE_LIMIT_MAX || 100);
const WINDOW_SECONDS = Number(process.env.RATE_LIMIT_WINDOW || 60);

export const rateLimiter = asyncHandler(async (req, res, next) => {
  if (!redis) {
    return next();
  }

  const key = `ratelimit:${req.ip}`;
  const pipeline = redis.multi();
  pipeline.incr(key);
  pipeline.expire(key, WINDOW_SECONDS);

  const [incrResult] = await pipeline.exec();
  const requestCount = incrResult?.[1] ?? 1;

  if (requestCount > MAX_REQUESTS) {
    res.setHeader("Retry-After", WINDOW_SECONDS.toString());
    return res
      .status(429)
      .json({ message: "Too many requests. Please slow down." });
  }

  return next();
});

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { useLocale } from "@/contexts/LocaleContext";
import { motion } from "framer-motion";
import { toast } from "sonner";

export function AuthPage() {
  const { login, register } = useAuth();
  const { t } = useLocale();
  const [mode, setMode] = useState("login");
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [loading, setLoading] = useState(false);

  const onSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    try {
      if (mode === "login") {
        await login({ email: form.email, password: form.password });
        toast.success("Welcome back!");
      } else {
        await register(form);
        toast.success("Account created!");
      }
    } catch (error) {
      toast.error("Authentication failed", {
        description: error.message,
      });
    } finally {
      setLoading(false);
    }
  };

  const toggleMode = () => {
    setMode((prev) => (prev === "login" ? "signup" : "login"));
  };

  return (
    <div className="flex min-h-screen flex-col items-center justify-center bg-[hsl(var(--background))] px-4 py-10 text-[hsl(var(--foreground))]">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="mx-auto flex w-full max-w-4xl flex-col gap-10 lg:flex-row"
      >
        <div className="flex flex-1 flex-col justify-center gap-4">
          <span className="w-max rounded-full bg-[hsla(var(--primary)_/_0.15)] px-4 py-1 text-xs font-semibold uppercase tracking-wide text-[hsl(var(--primary))]">
            GrowthMonitor
          </span>
          <h1 className="font-display text-4xl font-semibold leading-tight text-[hsl(var(--foreground))] md:text-5xl">
            {t("welcomeHeadline")}
          </h1>
          <p className="max-w-md text-base text-[hsl(var(--muted-foreground))]">
            {t("welcomeTagline")}
          </p>
          <div className="mt-6 flex flex-wrap gap-3">
            {["AI Revenue Insights", "Campaign Intelligence", "Bangla Support"].map(
              (pill) => (
                <span
                  key={pill}
                  className="rounded-full bg-white/60 px-4 py-2 text-xs font-semibold uppercase tracking-wide text-[hsl(var(--muted-foreground))] shadow-sm"
                >
                  {pill}
                </span>
              ),
            )}
          </div>
        </div>

        <Card className="flex-1">
          <CardHeader>
            <CardTitle className="text-2xl font-semibold">
              {mode === "login" ? t("login") : t("signup")}
            </CardTitle>
            <CardDescription>
              {mode === "login" ? t("welcomeBack") : "Start tracking growth in minutes."}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form className="flex flex-col gap-4" onSubmit={onSubmit}>
              {mode === "signup" && (
                <Input
                  required
                  placeholder={t("name")}
                  value={form.name}
                  onChange={(event) =>
                    setForm((prev) => ({ ...prev, name: event.target.value }))
                  }
                />
              )}
              <Input
                type="email"
                required
                placeholder={t("email")}
                value={form.email}
                onChange={(event) =>
                  setForm((prev) => ({ ...prev, email: event.target.value }))
                }
              />
              <Input
                type="password"
                required
                placeholder={t("password")}
                value={form.password}
                onChange={(event) =>
                  setForm((prev) => ({ ...prev, password: event.target.value }))
                }
              />

              <Button type="submit" disabled={loading}>
                {loading ? "..." : t("continue")}
              </Button>
            </form>

            <div className="mt-6 text-center text-sm text-[hsl(var(--muted-foreground))]">
              {mode === "login" ? (
                <>
                  {t("needAccount")}{" "}
                  <button
                    type="button"
                    onClick={toggleMode}
                    className="font-medium text-[hsl(var(--primary))] underline-offset-4 hover:underline"
                  >
                    {t("signup")}
                  </button>
                </>
              ) : (
                <>
                  {t("haveAccount")}{" "}
                  <button
                    type="button"
                    onClick={toggleMode}
                    className="font-medium text-[hsl(var(--primary))] underline-offset-4 hover:underline"
                  >
                    {t("login")}
                  </button>
                </>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>
    </div>
  );
}

// Role-based access control utilities

/**
 * User roles in the system
 */
export const ROLES = {
    OWNER: 'OWNER',
    ADMIN: 'ADMIN',
    MEMBER: 'MEMBER',
    VIEWER: 'VIEWER',
};

/**
 * Role display configuration
 */
export const ROLE_CONFIG = {
    OWNER: {
        label: 'Owner',
        color: 'text-yellow-600',
        bgColor: 'bg-yellow-100 dark:bg-yellow-900/20',
        borderColor: 'border-yellow-300',
        description: 'Full access to all features and settings',
    },
    ADMIN: {
        label: 'Admin',
        color: 'text-blue-600',
        bgColor: 'bg-blue-100 dark:bg-blue-900/20',
        borderColor: 'border-blue-300',
        description: 'Manage team members and data',
    },
    MEMBER: {
        label: 'Member',
        color: 'text-green-600',
        bgColor: 'bg-green-100 dark:bg-green-900/20',
        borderColor: 'border-green-300',
        description: 'View and manage data',
    },
    VIEWER: {
        label: 'Viewer',
        color: 'text-gray-600',
        bgColor: 'bg-gray-100 dark:bg-gray-900/20',
        borderColor: 'border-gray-300',
        description: 'Read-only access',
    },
};

/**
 * Check if user has a specific role
 * @param {object} user - User object with role property
 * @param {string|string[]} roles - Role or array of roles to check
 * @returns {boolean}
 */
export const hasRole = (user, roles) => {
    if (!user?.role) return false;
    const userRole = user.role.toUpperCase();
    const allowedRoles = Array.isArray(roles)
        ? roles.map(r => r.toUpperCase())
        : [roles.toUpperCase()];
    return allowedRoles.includes(userRole);
};

/**
 * Check if user is owner
 * @param {object} user - User object with role property
 * @returns {boolean}
 */
export const isOwner = (user) => hasRole(user, ROLES.OWNER);

/**
 * Check if user is admin or owner
 * @param {object} user - User object with role property
 * @returns {boolean}
 */
export const isAdminOrOwner = (user) => hasRole(user, [ROLES.OWNER, ROLES.ADMIN]);

/**
 * Check if user can manage data (not viewer)
 * @param {object} user - User object with role property
 * @returns {boolean}
 */
export const canManageData = (user) => hasRole(user, [ROLES.OWNER, ROLES.ADMIN, ROLES.MEMBER]);

/**
 * Get role display config
 * @param {string} role - User role
 * @returns {object}
 */
export const getRoleConfig = (role) => {
    const normalizedRole = role?.toUpperCase() || ROLES.VIEWER;
    return ROLE_CONFIG[normalizedRole] || ROLE_CONFIG[ROLES.VIEWER];
};

/**
 * Get role label for display
 * @param {string} role - User role
 * @returns {string}
 */
export const getRoleLabel = (role) => {
    return getRoleConfig(role).label;
};

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { toast } from "sonner";

const AuthContext = createContext(null);

const STORAGE_KEYS = {
  token: "gm_access_token",
  user: "gm_user",
};

const API_BASE_URL = import.meta.env.VITE_API_URL ?? "http://localhost:8080/api";

const fetchJson = async (input, init) => {
  const response = await fetch(input, init);
  const text = await response.text();
  let parsed;
  if (text) {
    try {
      parsed = JSON.parse(text);
    } catch {
      parsed = text;
    }
  }
  if (!response.ok) {
    const error = new Error(parsed?.message || response.statusText);
    error.status = response.status;
    error.payload = parsed;
    throw error;
  }
  return parsed;
};

export function AuthProvider({ children }) {
  const [accessToken, setAccessToken] = useState(() =>
    localStorage.getItem(STORAGE_KEYS.token),
  );
  const [user, setUser] = useState(() => {
    const stored = localStorage.getItem(STORAGE_KEYS.user);
    return stored ? JSON.parse(stored) : null;
  });
  const [initializing, setInitializing] = useState(true);
  const refreshInFlight = useRef(null);

  const persistSession = useCallback((nextUser, token) => {
    if (nextUser) {
      localStorage.setItem(STORAGE_KEYS.user, JSON.stringify(nextUser));
      setUser(nextUser);
    }
    if (token) {
      localStorage.setItem(STORAGE_KEYS.token, token);
      setAccessToken(token);
    }
  }, []);

  const clearSession = useCallback(() => {
    localStorage.removeItem(STORAGE_KEYS.user);
    localStorage.removeItem(STORAGE_KEYS.token);
    setUser(null);
    setAccessToken(null);
  }, []);

  const refreshAccessToken = useCallback(async () => {
    if (refreshInFlight.current) {
      return refreshInFlight.current;
    }
    refreshInFlight.current = fetchJson(`${API_BASE_URL}/auth/refresh`, {
      method: "POST",
      credentials: "include",
    })
      .then((data) => {
        if (data?.accessToken) {
          persistSession(user ?? null, data.accessToken);
        }
        return data?.accessToken ?? null;
      })
      .catch((error) => {
        console.error("Failed to refresh token", error);
        clearSession();
        return null;
      })
      .finally(() => {
        refreshInFlight.current = null;
      });
    return refreshInFlight.current;
  }, [clearSession, persistSession, user]);

  const apiFetch = useCallback(
    async (path, { auth = true, headers = {}, ...options } = {}, retry = true) => {
      const requestInit = {
        credentials: "include",
        ...options,
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          ...headers,
        },
      };

      if (options?.body instanceof FormData) {
        delete requestInit.headers["Content-Type"];
      }

      let token = accessToken;
      if (auth) {
        if (!token) {
          token = await refreshAccessToken();
        }
        if (token) {
          requestInit.headers.Authorization = `Bearer ${token}`;
        }
      }

      try {
        return await fetchJson(`${API_BASE_URL}${path}`, requestInit);
      } catch (error) {
        if (error.status === 401 && retry) {
          const newToken = await refreshAccessToken();
          if (newToken) {
            return apiFetch(path, { auth, headers, ...options }, false);
          }
        }
        throw error;
      }
    },
    [accessToken, refreshAccessToken],
  );

  const login = useCallback(
    async ({ email, password }) => {
      const payload = await fetchJson(`${API_BASE_URL}/auth/login`, {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      if (payload?.accessToken) {
        persistSession(payload.user, payload.accessToken);
      }
      return payload;
    },
    [persistSession],
  );

  const register = useCallback(
    async ({ name, email, password }) => {
      const payload = await fetchJson(`${API_BASE_URL}/auth/register`, {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email, password }),
      });
      if (payload?.accessToken) {
        persistSession(payload.user, payload.accessToken);
      }
      return payload;
    },
    [persistSession],
  );

  const logout = useCallback(async () => {
    try {
      await fetchJson(`${API_BASE_URL}/auth/logout`, {
        method: "POST",
        credentials: "include",
      });
    } catch (error) {
      console.warn("Logout request failed", error);
    } finally {
      clearSession();
    }
  }, [clearSession]);

  useEffect(() => {
    let cancelled = false;
    const bootstrap = async () => {
      if (accessToken && user) {
        setInitializing(false);
        return;
      }
      try {
        const refreshed = await refreshAccessToken();
        if (refreshed && !cancelled) {
          const profile = await apiFetch("/auth/me");
          persistSession(profile?.user ?? null, refreshed);
        }
      } catch (error) {
        console.warn("Bootstrap auth failed", error);
        clearSession();
      } finally {
        if (!cancelled) setInitializing(false);
      }
    };
    bootstrap();
    return () => {
      cancelled = true;
    };
  }, [accessToken, apiFetch, clearSession, persistSession, refreshAccessToken, user]);

  const value = useMemo(
    () => ({
      user,
      accessToken,
      initializing,
      login,
      register,
      logout,
      apiFetch,
      refreshAccessToken,
      setUser: (nextUser) => {
        persistSession(nextUser, accessToken);
      },
      showError: (message, description) =>
        toast.error(message, { description }),
      showSuccess: (message, description) =>
        toast.success(message, { description }),
    }),
    [
      accessToken,
      apiFetch,
      initializing,
      login,
      logout,
      register,
      refreshAccessToken,
      persistSession,
      user,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return ctx;
};

