import "dotenv/config";
import http from "http";
import app from "./app.js";
import {
  disconnectPrisma,
  initPrisma,
} from "./services/prisma.service.js";
import {
  disconnectRedis,
  initRedis,
} from "./services/redis.service.js";

const port = Number(process.env.PORT || 8080);

const server = http.createServer(app);

const start = async () => {
  try {
    await initPrisma();
    await initRedis();
    server.listen(port, () => {
      console.log(`API server listening on port ${port}`);
    });
  } catch (error) {
    console.error("Failed to start server", error);
    process.exit(1);
  }
};

const gracefulShutdown = async (signal) => {
  console.log(`Received ${signal}. Shutting down gracefully...`);
  server.close(async () => {
    await disconnectRedis();
    await disconnectPrisma();
    process.exit(0);
  });
};

["SIGINT", "SIGTERM"].forEach((signal) => {
  process.on(signal, () => gracefulShutdown(signal));
});

start();

import cookieParser from "cookie-parser";
import cors from "cors";
import express from "express";
import morgan from "morgan";
import routes from "./routes/index.js";
import { rateLimiter } from "./middlewares/rateLimiter.middleware.js";
import {
  errorHandler,
  notFoundHandler,
} from "./middlewares/error.middleware.js";

const app = express();
// CORS_ORIGINS=http://localhost:3000,http://localhost:5173
// convert to array from env variable
const CORS_ORIGINS_URLS = process.env.CORS_ORIGINS;

const corsOrigins = CORS_ORIGINS_URLS
  ? CORS_ORIGINS_URLS.split(",").map((origin) => origin.trim())
  : ["http://localhost:3000", "http://localhost:5173"];

app.use(
  cors({
    origin: (origin, callback) => {
      if (!origin || corsOrigins.includes(origin)) {
        return callback(null, origin ?? corsOrigins[0]);
      }
      return callback(new Error("Not allowed by CORS"));
    },
    credentials: true,
  }),
);

app.use(morgan("dev"));
app.use(express.json({ limit: "1mb" }));
app.use(express.urlencoded({ extended: true }));
app.use(cookieParser());
app.use(rateLimiter);

app.get("/healthz", (req, res) => {
  res.json({ status: "ok" });
});

app.head("/healthz", (req, res) => {
  res.send();
});

app.use("/api", routes);

app.use(notFoundHandler);
app.use(errorHandler);

export default app;

